WITH RankedPosts AS (SELECT P.Id AS PostId, P.Title, U.DisplayName AS OwnerName, P.CreationDate, P.Score, P.ViewCount, ROW_NUMBER() OVER (PARTITION BY P.PostTypeId ORDER BY P.Score DESC NULLS FIRST) AS PostRank FROM Posts AS P JOIN Users AS U ON P.OwnerUserId = U.Id WHERE P.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), RecentComments AS (SELECT C.PostId, COUNT(*) AS CommentCount, MAX(C.CreationDate) AS LastCommentDate FROM Comments AS C GROUP BY C.PostId), PostHistorySummary AS (SELECT PH.PostId, COUNT(*) AS HistoryCount, GROUP_CONCAT(PHT.Name, ', ') AS HistoryTypes FROM PostHistory AS PH JOIN PostHistoryTypes AS PHT ON PH.PostHistoryTypeId = PHT.Id GROUP BY PH.PostId) SELECT RP.PostId, RP.Title, RP.OwnerName, RP.CreationDate, RP.Score, RP.ViewCount, COALESCE(RC.CommentCount, 0) AS CommentCount, COALESCE(RC.LastCommentDate, NULL) AS LastCommentDate, COALESCE(PHS.HistoryCount, 0) AS PostHistoryCount, COALESCE(PHS.HistoryTypes, 'No history') AS PostHistoryTypes FROM RankedPosts AS RP LEFT JOIN RecentComments AS RC ON RP.PostId = RC.PostId LEFT JOIN PostHistorySummary AS PHS ON RP.PostId = PHS.PostId WHERE RP.PostRank <= 5 ORDER BY RP.Score DESC NULLS FIRST